import com.sun.net.httpserver.*;
import javax.net.ssl.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.*;import java.util.*;import java.util.concurrent.TimeUnit;import java.util.concurrent.atomic.AtomicInteger;
public class RedirectVariants {
 static String enc(String v){return Base64.getUrlEncoder().withoutPadding().encodeToString(v.getBytes(StandardCharsets.UTF_8));}
 public static void main(String[] args) throws Exception {
  int status=Integer.parseInt(args[0]);String mode=args[1];char[] pw="synthetic".toCharArray();KeyStore ks=KeyStore.getInstance("PKCS12");
  try(InputStream i=Files.newInputStream(Path.of("/test/server.p12"))){ks.load(i,pw);}
  KeyManagerFactory km=KeyManagerFactory.getInstance(KeyManagerFactory.getDefaultAlgorithm());km.init(ks,pw);SSLContext ctx=SSLContext.getInstance("TLS");ctx.init(km.getKeyManagers(),null,null);
  HttpsServer src=HttpsServer.create(new InetSocketAddress("127.0.0.1",0),0),dest=HttpsServer.create(new InetSocketAddress(mode.equals("crossip")?"127.0.0.2":"127.0.0.1",0),0);src.setHttpsConfigurator(new HttpsConfigurator(ctx));dest.setHttpsConfigurator(new HttpsConfigurator(ctx));
  AtomicInteger seen=new AtomicInteger(), destCount=new AtomicInteger(),destAuth=new AtomicInteger(),destWsAuth=new AtomicInteger(),destWs=new AtomicInteger(),destOriginAuth=new AtomicInteger(),sourceWs=new AtomicInteger();
  HttpHandler destination=ex->{destCount.incrementAndGet();String origin=ex.getRequestHeaders().getFirst("Origin");if(origin!=null&&(origin.contains("synthetic-test-secret")||origin.contains(enc("X-Workspace-Token=synthetic-test-secret"))))destOriginAuth.incrementAndGet();String proto=ex.getRequestHeaders().getFirst("Sec-WebSocket-Protocol");if(proto!=null){destWs.incrementAndGet();if(proto.contains(enc("X-Workspace-Token=synthetic-test-secret")))destWsAuth.incrementAndGet();}if("synthetic-test-secret".equals(ex.getRequestHeaders().getFirst("X-Workspace-Token")))destAuth.incrementAndGet();byte[] b="{}".getBytes();ex.sendResponseHeaders(200,b.length);ex.getResponseBody().write(b);ex.close();};dest.createContext("/",destination);src.createContext("/capture",destination);
  src.createContext("/",ex->{if(ex.getRequestHeaders().getFirst("Sec-WebSocket-Protocol")!=null)sourceWs.incrementAndGet();if(ex.getRequestURI().getPath().contains("/manager/device/topologies"))seen.incrementAndGet();ex.getResponseHeaders().set("Location",(mode.equals("samepath")?"":mode.equals("samehost")?"https://localhost:"+src.getAddress().getPort():"https://"+(mode.equals("crossip")?"127.0.0.2":"127.0.0.1")+":"+dest.getAddress().getPort())+"/capture");byte[] b="{\"code\":0,\"data\":{\"pagination\":{\"page_num\":1,\"page_size\":1000,\"total\":0},\"list\":[]}}".getBytes();if(ex.getRequestHeaders().getFirst("Sec-WebSocket-Protocol")!=null){ex.sendResponseHeaders(status,-1);}else{ex.sendResponseHeaders(status,b.length);ex.getResponseBody().write(b);}ex.close();});
  src.start();dest.start(); ProcessBuilder pb=new ProcessBuilder("java","-cp","/test/out:/sdk/flight-hub-sdk-patched.jar","DjiCloud2Bridge");pb.redirectError(ProcessBuilder.Redirect.DISCARD);Process p=pb.start();String h=enc("X-Workspace-Token"),secret=enc("synthetic-test-secret");
  String init="INIT\t1\t"+enc("127.0.0.1")+"\t"+src.getAddress().getPort()+"\t1\t"+h+"\t"+secret+"\t1\t"+h+"\t"+secret+"\n";
  try(OutputStream w=p.getOutputStream()){w.write((init+"LIST\t77fb733a-7dc0-4a94-9bc3-756f487bf854\n").getBytes(StandardCharsets.US_ASCII));w.flush();Thread.sleep(2500);try{w.write("CLOSE\n".getBytes(StandardCharsets.US_ASCII));}catch(IOException ignored){}}
  boolean done=p.waitFor(30,TimeUnit.SECONDS);if(!done)p.destroyForcibly();String output=new String(p.getInputStream().readAllBytes(),StandardCharsets.US_ASCII);src.stop(0);dest.stop(0);
  System.out.println("mode="+mode+" status="+status+" source_requests="+seen.get()+" source_ws="+sourceWs.get()+" destination_requests="+destCount.get()+" destination_received_auth="+destAuth.get()+" destination_ws="+destWs.get()+" destination_ws_contains_auth="+destWsAuth.get()+" destination_origin_contains_auth="+destOriginAuth.get()+" incorrectly_reported_success="+output.contains("RESULT\t")+" timeout="+!done);
 }
}
